#include <bits/stdc++.h>
using namespace std;

vector<int> create_tree(int size) {
    int i = 2;
    while (true) {
        if (i >= size * 2) {
            return vector<int>(i, 0);
        }
        i *= 2;
    }
}

void update_value(vector<int>& tree, int size, int i, int val) {
    int idx = i + size / 2;
    tree[idx] = val;
    idx /= 2;
    while (idx > 0) {
        tree[idx] = tree[2 * idx] + tree[2 * idx + 1];
        idx /= 2;
    }
}

int sum_range(const vector<int>& tree, int size, int s, int t) {
    s += size / 2;
    t += size / 2;
    int total = 0;
    while (s <= t) {
        if (s % 2 == 0) {
            s /= 2;
        } else {
            total += tree[s];
            s = (s + 1) / 2;
        }
        if (t % 2 == 1) {
            total += tree[t];
            t = (t - 1) / 2;
        } else {
            t /= 2;
        }
    }
    return total;
}

vector<long long> prime_decompose(long long n) {
    vector<long long> factors;
    for (long long i = 2; i * i <= n; ++i) {
        while (n % i == 0) {
            factors.push_back(i);
            n /= i;
        }
        if (n == 1) break;
    }
    if (n != 1) {
        factors.push_back(n);
    }
    return factors;
}

long long totient(long long n) {
    unordered_set<long long> p_factors;
    for (auto p : prime_decompose(n)) {
        p_factors.insert(p);
    }
    long long result = n;
    for (auto p : p_factors) {
        result = result * (p - 1) / p;
    }
    return result;
}

long long product_mod(long long a, long long b, long long mod) {
    long long res = 1;
    for (long long i = a + 1; i <= b; ++i) {
        res = (res * i) % mod;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long mod;
    cin >> n >> mod;
    long long phi_value = totient(mod);
    int max_length = n + 5;
    vector<long long> fact_list(max_length + 1, 1);
    for (int i = 1; i <= max_length; ++i) {
        fact_list[i] = (fact_list[i - 1] * i) % mod;
    }

    if (n <= 3) {
        cout << 0 << "\n";
        return 0;
    }

    vector<long long> dp_array(2000, 0);
    dp_array[0] = 1;
    dp_array[1] = 2;
    dp_array[2] = 2;
    dp_array[3] = 1;

    vector<int> tree = create_tree(2005);
    for (int i = 0; i < 4; ++i) {
        update_value(tree, (int)tree.size(), i, dp_array[i]);
    }

    int m = 3;
    long long answer = 0;

    for (int i = 0; i < n - 3; ++i) {
        vector<long long> prev_dp = dp_array;
        long long sum_partial = 0;
        for (int j = 0; j <= i + 2; ++j) {
            for (int k = 1; k <= m + 1; ++k) {
                long long sum_val = sum_range(tree, (int)tree.size(), j + k + 1, 2004);
                sum_partial = (sum_partial + sum_val * prev_dp[k - 1]) % mod;
                dp_array[j + k] = (dp_array[j + k] + prev_dp[k - 1]) % mod;
                update_value(tree, (int)tree.size(), j + k, dp_array[j + k]);
            }
        }
        m += i + 3;
        long long numerator = product_mod(i + 4, n, mod);
        answer = (answer + numerator * sum_partial) % mod;
    }

    cout << answer << "\n";

    return 0;
}
